]+e)>>>0;H[5]=(H[5]+f)>>>0;H[6]=(H[6]+g)>>>0;H[7]=(H[7]+h)>>>0;}const out=new Uint8Array(32),odv=new DataView(out.buffer);for(let i=0;i<8;i++)odv.setUint32(i*4,H[i],false);return out;}
function sha256Hex(d){return Array.from(sha256(d)).map(b=>b.toString(16).padStart(2,'0')).join('');}
function hmacSha256(k,m){const block=64;let key=k.length>block?sha256(k):k;const kk=new Uint8Array(block);kk.set(key);const ip=kk.map(b=>b^0x36),op=kk.map(b=>b^0x5c),mb=typeof m==='string'?(new TextEncoder()).encode(m):m,inner=new Uint8Array(block+mb.length),outer=new Uint8Array(block+32);inner.set(ip);inner.set(mb,block);outer.set(op);outer.set(sha256(inner),block);return sha256(outer);}
function hmacHex(k,m){return Array.from(hmacSha256(k,m)).map(b=>b.toString(16).padStart(2,'0')).join('');}

function getSigningKey(secret,date,region,service){const enc=s=>(new TextEncoder()).encode(s);const kDate=hmacSha256(enc('AWS4'+secret),date),kRegion=hmacSha256(kDate,region),kService=hmacSha256(kRegion,service);return hmacSha256(kService,'aws4_request');}

function cleanText(v){return typeof v==='string'?v.trim():String(v||'').trim();}
function getField(obj,...names){const clean=Object.fromEntries(Object.entries(obj||{}).map(([k,v])=>[k.replace(/^\uFEFF/,'').toLowerCase(),v]));for(const name of names){const val=clean[name.toLowerCase()];if(val!==undefined&&val!==null&&val!=='')return val;}return '';}
function extractDriveId(value){const raw=cleanText(value);if(!raw)return '';if(!/^https?:\/\//i.test(raw))return raw;try{const url=new URL(raw);const p=cleanText(url.searchParams.get('id'));if(p)return p;const m=url.pathname.match(/\/file\/d\/([^/]+)/i)||url.pathname.match(/\/d\/([^/]+)/i);return m?cleanText(m[1]):'';}catch{return '';}}

// ── Dados do Airtable ──
const src      = $json.fields || $json;
const recordId = cleanText($json.id || $json.recordId);
const title    = cleanText(getField(src,'Title','title','name')) || 'Untitled';
const googleId = cleanText(getField(src,'Google ID','googleId','google_id','googleID'));
const link     = cleanText(getField(src,'Link','link','url'));

if (!recordId) throw new Error('recordId ausente no registro Airtable');

let downloadUrl = '';
if (/^https?:\/\//i.test(link)) {
  downloadUrl = link;
} else {
  const driveId = extractDriveId(googleId) || extractDriveId(link);
  if (driveId) downloadUrl = `https://drive.usercontent.google.com/download?id=${encodeURIComponent(driveId)}&export=download&confirm=t`;
}
if (!downloadUrl) throw new Error(`Nenhuma URL de download para record ${recordId}`);

const objectKey   = `bbt/${recordId}.mp4`;
const contentType = 'video/mp4';

// ── AWS Sig V4 com UNSIGNED-PAYLOAD ──
const region = 'auto', service = 's3';
const host   = `${R2_ACCOUNT_ID}.r2.cloudflarestorage.com`;
const now    = new Date();
const amzDate   = now.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
const dateStamp = amzDate.slice(0,8);
const payloadHash = 'UNSIGNED-PAYLOAD';

const canonicalHeaders =
  `content-type:${contentType}\n` +
  `host:${host}\n` +
  `x-amz-content-sha256:${payloadHash}\n` +
  `x-amz-date:${amzDate}\n`;
const signedHeaders    = 'content-type;host;x-amz-content-sha256;x-amz-date';
const canonicalRequest = ['PUT',`/${R2_BUCKET}/${objectKey}`,'',canonicalHeaders,signedHeaders,payloadHash].join('\n');
const credentialScope  = `${dateStamp}/${region}/${service}/aws4_request`;
const stringToSign     = ['AWS4-HMAC-SHA256',amzDate,credentialScope,sha256Hex(canonicalRequest)].join('\n');
const sigKey           = getSigningKey(R2_SECRET_ACCESS_KEY,dateStamp,region,service);
const signature        = hmacHex(sigKey,stringToSign);

const authorization = `AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY_ID}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
const uploadUrl     = `https://${host}/${R2_BUCKET}/${objectKey}`;
const r2Url         = `${R2_PUBLIC_BASE.replace(/\/$/,'')}/${objectKey}`;

return { json: { recordId, title, googleId, downloadUrl, objectKey, contentType, authorization, payloadHash, amzDate, uploadUrl, r2Url } };
